import React from "react"
import { inknut } from "@/app/fonts"

export type SocialLink = {
  id: string
  href: string
  icon?: React.ReactNode
  label?: string
}

type Props = {
  businessName: string
  displayName: string // gray line under business name
  profileImageUrl?: string
  socialLinks?: SocialLink[]
  merchTags?: string[]
  previousVends?: string[]
  locationText?: string // "City, State" or "City, Country"
  email?: string
}

export default function ProfileSidebar({
  businessName,
  displayName,
  profileImageUrl,
  socialLinks = [],
  merchTags = [],
  previousVends = [],
  locationText = "City, State",
  email = "myemailaddress@konfolio.com",
}: Props) {
  return (
    <aside
      className="
        relative
        w-[316px] h-[982px]
        bg-white
        flex flex-col items-center justify-between
        px-[20px] py-[40px]
      "
    >
      {/* watermark logo (top center, faint) */}
      <div className="pointer-events-none absolute top-[30px] left-1/2 -translate-x-1/2 opacity-50">
        <span
          className={`${inknut.className} text-[18.12px] leading-[100%] tracking-[-0.02em] font-semibold text-[#262626]`}
          style={{ WebkitTextStroke: "0.712187px #262626" }}
        >
          konfolio
        </span>
      </div>

      {/* Main profile stack */}
      <div className="w-[276px] flex flex-col items-center gap-[30px] pt-[30px]">
        {/* Image + names */}
        <div className="w-[276px] flex flex-col items-center gap-[12px]">
          <div className="w-[189px] h-[189px] rounded-[15px] overflow-hidden bg-[#A5A5A5]/10">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            {profileImageUrl ? (
              <img
                src={profileImageUrl}
                alt={`${businessName} profile`}
                className="w-full h-full object-cover"
              />
            ) : (
              <div className="w-full h-full" />
            )}
          </div>

          <p className="m-0 w-full text-center font-inter font-normal text-[22px] leading-[27px] text-[#262626]">
            {businessName}
          </p>

          <p className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
            {displayName}
          </p>
        </div>

        {/* Social links row */}
        <div className="w-[276px] h-[24px] flex items-center justify-center gap-[10px]">
          {socialLinks.length === 0 ? null : (
            socialLinks.map((l) => (
              <a
                key={l.id}
                href={l.href}
                target="_blank"
                rel="noreferrer"
                className="w-[24px] h-[24px] grid place-items-center"
                aria-label={l.label ?? "social link"}
              >
                {l.icon ?? (
                  <span className="w-[24px] h-[24px] rounded-full border border-[#262626]" />
                )}
              </a>
            ))
          )}
        </div>

        {/* Merch tags */}
        <div className="w-[276px] flex flex-wrap justify-center items-start content-center gap-[10px]">
          {merchTags.slice(0, 6).map((t) => (
            <span
              key={t}
              className="
                inline-flex items-center justify-center
                px-[22px] py-[7px]
                border border-[#A5A5A5]/50
                rounded-[100px]
                font-inter font-normal text-[15px] leading-[140%]
                text-[#A5A5A5]
                whitespace-nowrap
              "
            >
              {t}
            </span>
          ))}
        </div>

        {/* Previous vends */}
        <div className="w-[276px] flex flex-col items-center gap-[12px]">
          <p className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
            Previous Vends
          </p>

          {previousVends.length === 0 ? (
            <p className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
              —
            </p>
          ) : (
            <p className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#262626]">
              {previousVends[0]}
            </p>
          )}
        </div>

        {/* Location + email */}
        <div className="w-[276px] flex flex-col items-center gap-[12px]">
          <div className="flex items-center justify-center gap-[5px]">
            {/* swap this for your real LocationIcon if you have one */}
            <span className="w-[12px] h-[12px] bg-[#A5A5A5] rounded-sm" />
            <p className="m-0 font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
              {locationText}
            </p>
          </div>

          <p className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
            {email}
          </p>
        </div>
      </div>

      {/* Bottom spacer (keeps “justify-between” feel from Figma) */}
      <div className="h-[10px]" />
    </aside>
  )
}
